#include <string>
#include <algorithm>

class Solution {
public:
    long long maximumSubsequenceCount(std::string text, std::string pattern) {
        char p0 = pattern[0], p1 = pattern[1];
        long long c0 = 0, c1 = 0;
        long long base_count = 0;

        for (char ch : text) {
            if (ch == p1) {
                base_count += c0;
                c1++;
            }
            if (ch == p0) {
                c0++;
            }
        }

        return base_count + std::max(c0, c1);
    }
};

class Solution {
    public long maximumSubsequenceCount(String text, String pattern) {
        char p0 = pattern.charAt(0), p1 = pattern.charAt(1);
        long c0 = 0, c1 = 0;
        long baseCount = 0;

        for (int i = 0; i < text.length(); i++) {
            char ch = text.charAt(i);
            if (ch == p1) {
                baseCount += c0;
                c1++;
            }
            if (ch == p0) {
                c0++;
            }
        }

        return baseCount + Math.max(c0, c1);
    }
}

